def build_agent(sandbox):
    # Create a pivot beam at (10, 5) m
    pivot = sandbox.add_beam(x=10, y=5, width=0.1, height=0.1, density=100.0)
    return pivot

def agent_action(sandbox, agent_body, step_count):
    if step_count == 0:
        projectile = sandbox.get_projectile()
        # Apply a force to compress the spring initially
        sandbox.ApplyForceToCenter(projectile, (0, -500), projectile.position)
